#!/bin/sh
# Container start: if no BACKEND_API_KEY is given, use the key generated by
# docker compose (api-key-init) so it matches the backend; then run the CMD.
set -e

if [ -z "${BACKEND_API_KEY:-}" ] && [ -r /run/sunrise/api_key ]; then
  BACKEND_API_KEY="$(cat /run/sunrise/api_key)"
  export BACKEND_API_KEY
fi

exec "$@"
